import sys

def main():
    import sys
    import bisect

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n = readints()[0]
    points = readints()

    events = []
    for i, x in enumerate(points):
        events.append((x, 1, i))  # Start of semicircle
        events.append((x + 1, -1, i))  # End of semicircle

    events.sort()

    active = []
    for x, typ, idx in events:
        if typ == 1:
            bisect.insort(active, idx)
        else:
            active.remove(idx)

        # Check for intersections
        if len(active) >= 2:
            mid = len(active) // 2
            if abs(points[active[mid]] - points[active[mid - 1]]) < 1:
                print("yes")
                return

    print("no")

if __name__ == "__main__":
    main()
